          "properties": {
            "explorer": {
              "$id": "#/properties/global/properties/tools/properties/explorer",
              "title": "Blockchain Explorer enabled",
              "type": "boolean"
            }
          }
        }
      }
    },
    "orgs": {
      "$id": "#/properties/orgs",
      "title": "Organizations",
      "type": "array",
      "default": [
        {
          "organization": {
            "name": "Orderer",
            "mspName": "OrdererMSP",
            "domain": "orderer.example.com"
          },
          "ca": {
            "prefix": "ca"
          },
          "orderer": {
            "prefix": "orderer",
            "type": "solo",
            "instances": 1
          }
        },
        {
          "organization": {
            "name": "Org1",
            "mspName": "Org1MSP",
            "domain": "org1.example.com"
          },
          "ca": {
            "prefix": "ca"
          },
          "peer": {
            "instances": 2,
            "prefix": "peer",
            "db": "LevelDb"
          }
        }
      ],
      "items": {
        "$id": "#/properties/orgs/items",
        "title": "Organization",
        "type": "object",
        "required": [
          "organization"
        ],
        "properties": {
          "organization": {
            "$id": "#/properties/orgs/items/properties/organization",
            "title": "Basic information",
            "type": "object",
            "required": [
              "name",
              "domain"
            ],
            "properties": {
              "name": {
                "$id": "#/properties/orgs/items/properties/organization/properties/name",
                "title": "Name",
                "type": "string",
                "pattern": "^[a-zA-Z0-9]+$"
              },
              "mspName": {
                "$id": "#/properties/orgs/items/properties/organization/properties/mspName",
                "title": "MSP Name",
